# Sink policy scoped to a single AWS Organization
resource "aws_oam_sink_policy" "<example_resource_name>" {
  sink_identifier = "<example_resource_id>"
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = ["oam:CreateLink", "oam:UpdateLink"]
        Effect    = "Allow"
        Resource  = "*"
        Principal = "*"
        Condition = {
          # CRITICAL: without this condition any AWS account can link to the sink
          StringEquals = { "aws:PrincipalOrgID" = "<example_resource_id>" }
        }
      }
    ]
  })
}
```
